async function scanBundle(input, deliver) {
  const decoder = new TextDecoder("utf-8");
  const parts = [];
  const DECODE_CHUNK_SIZE = 65536;

  let line = 1;
  let delivered = 0;

  function takeLine(tail) {
    let text;

    if (parts.length === 0) {
      text = tail;
    } else {
      parts.push(tail);
      text = parts.join("");
      parts.length = 0;
    }

    if (text.endsWith("\r")) {
      text = text.slice(0, -1);
    }

    return text;
  }

  async function emit(text) {
    const currentLine = line++;

    if (/^[\u0009\u000D\u0020]*$/.test(text)) {
      return false;
    }

    let value;
    try {
      value = JSON.parse(text);
    } catch {
      const error = new Error(`Invalid JSON on line ${currentLine}`);
      error.code = "BAD_LINE";
      error.line = currentLine;
      throw error;
    }

    delivered++;
    return (await deliver(value, currentLine)) === false;
  }

  async function consume(text) {
    let start = 0;

    while (true) {
      const end = text.indexOf("\n", start);
      if (end === -1) {
        if (start < text.length) {
          parts.push(text.slice(start));
        }
        return false;
      }

      if (await emit(takeLine(text.slice(start, end)))) {
        return true;
      }

      start = end + 1;
    }
  }

  try {
    while (true) {
      const bytes = await input.read();

      if (bytes === null) {
        const tail = decoder.decode();

        if (tail.length > 0 && await consume(tail)) {
          return delivered;
        }

        if (parts.length > 0 && await emit(takeLine(""))) {
          return delivered;
        }

        return delivered;
      }

      for (let offset = 0; offset < bytes.length; offset += DECODE_CHUNK_SIZE) {
        const end = Math.min(offset + DECODE_CHUNK_SIZE, bytes.length);
        const text = decoder.decode(bytes.subarray(offset, end), { stream: true });

        if (text.length > 0 && await consume(text)) {
          return delivered;
        }
      }
    }
  } finally {
    await input.close();
  }
}
